    public void testHandleWeirdNumberValue_HandlerReturnsNotHandled() throws IOException {
        DeserializationProblemHandler handler = mock(DeserializationProblemHandler.class);
        LinkedNode<DeserializationProblemHandler> node = mock(LinkedNode.class);

        when(handler.handleWeirdNumberValue(any(), any(), any(), anyString())).thenReturn(DeserializationProblemHandler.NOT_HANDLED);
        when(node.value()).thenReturn(handler);
        when(node.next()).thenReturn(null); // End of chain
        when(config.getProblemHandlers()).thenReturn(node);

        // Mock the exception throwing logic
        doThrow(new IOException("Final Exception")).when(context).handleWeirdNumberValue(eq(Integer.class), any(), anyString(), any());

        context.handleWeirdNumberValue(Integer.class, 123, "Error");
    }

